UPDATE ticket_inventory
SET reserved_quantity = reserved_quantity + #{quantity}, version = version + 1
WHERE ticket_time_slot_id = #{slotId}
  AND total_quantity - reserved_quantity >= #{quantity}

UPDATE ticket_inventory
SET reserved_quantity = reserved_quantity - #{quantity}, version = version + 1
WHERE ticket_time_slot_id = #{slotId}
  AND reserved_quantity >= #{quantity}

